import{_ as i}from"./chunks/failure-clustering-fingerprint.B8ggWE9V.js";import{_ as l}from"./chunks/failure-clusters-tab.CzmMvvxd.js";import{_ as h,C as t,o as d,c,j as r,a as u,E as s,a6 as a}from"./chunks/framework.CCKCzdWs.js";const _=JSON.parse('{"title":"Failure clusters & the inbox","description":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing.","frontmatter":{"title":"Failure clusters & the inbox","description":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/failure-clusters.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/failure-clusters.html"}],["meta",{"property":"og:title","content":"Failure clusters & the inbox | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing."}]]},"headers":[],"relativePath":"features/failure-clusters.md","filePath":"features/failure-clusters.md","lastUpdated":1794666855000}'),g={name:"features/failure-clusters.md"};function f(m,e,p,b,w,x){const n=t("Needs"),o=t("DemoExamples");return d(),c("div",null,[e[0]||(e[0]=r("h1",{id:"failure-clusters-the-inbox",tabindex:"-1"},[u("Failure clusters & the inbox "),r("a",{class:"header-anchor",href:"#failure-clusters-the-inbox","aria-label":'Permalink to "Failure clusters & the inbox"'},"​")],-1)),s(n,{reporter:""}),e[1]||(e[1]=a('<p>How Piwi groups failures by root cause into <strong>failure clusters</strong>, where a cluster stands, whether its fix worked, and the <strong>failure inbox</strong> on Home. A model&#39;s explanation is on <a href="./ai-diagnosis.html">AI diagnosis</a>, fixing on <a href="./fix-plans.html">Fix plans</a>.</p><h2 id="how-failures-are-grouped" tabindex="-1">How failures are grouped <a class="header-anchor" href="#how-failures-are-grouped" aria-label="Permalink to &quot;How failures are grouped&quot;">​</a></h2><p>Failed executions sharing an <strong>error fingerprint</strong> join one cluster: <em>&quot;20 failures, 3 root causes&quot;</em>. Always on, the fingerprint hashes the error type, message and locator, <strong>masking what varies</strong>: numbers, UUIDs, hashes, ids glued to an underscore (<code>order_5f3a9c1e2b</code>), URLs, emails, timestamps, the folders of a path under a home folder, CI workspace or Windows drive, a temporary folder&#39;s random suffix, an assertion&#39;s <em>expected</em> and <em>received</em> values, the elements a strict-mode violation lists, and dynamic locator options such as a row&#39;s <code>{ name: &#39;…&#39; }</code>. The locator&#39;s target (test id, role) still tells failures apart.</p><p>It <strong>ignores the failing stack frame</strong> when the error says what failed, so one root cause reached from several spec files, through a helper or page object, stays one cluster. A <strong>generic</strong> error says nothing of its own: it names no locator, and its message is an <code>expect(…)</code> matcher whose values are all masked, a test timeout, or a bare <code>TypeError</code> or <code>ReferenceError</code> line. Its fingerprint also hashes the file of its failing stack frame (the spec, or the helper).</p><p>A cluster keeps its first error, so an improved normalization <strong>regroups clusters in place</strong> with their triage, notes, diagnoses and merges. A run&#39;s <strong>Tests</strong> tab groups failures by cluster; <a href="/reference/mcp-tools.html#get_failure_groups"><code>get_failure_groups</code></a> adds a <strong>worker-correlation</strong> flag (&quot;worker 3 is misbehaving&quot;).</p><figure><img src="'+i+'" alt="The fingerprint pipeline: a raw error is normalized, hashed and routed to one cluster"></figure><p>With an embedding model, near-duplicates the fingerprint keeps apart are merged too (<a href="./ai-diagnosis.html#semantic-merging-optional">semantic merging</a>). <strong>A merge never buries a live failure</strong>: the survivor ends open when either cluster was open and not snoozed, takes the other&#39;s assignee when it has none, appends its note, and inherits its tickets, fix attempts, tracker history and the merges decided against.</p><h3 id="split-a-cluster-by-hand" tabindex="-1">Split a cluster by hand <a class="header-anchor" href="#split-a-cluster-by-hand" aria-label="Permalink to &quot;Split a cluster by hand&quot;">​</a></h3><p>When some tests fail with the same error for another reason, select them in <strong>Affected tests</strong> and choose <strong>Move to a new cluster</strong> (Maintainer or above; no AI). Their failures move to a new cluster with your note, the old one gains a line naming the move, their later failures with that error join the new one, and the two never merge automatically.</p><figure><img src="'+l+'" alt="A project&#39;s Failures tab: its open clusters with type, triage, tests and occurrences"></figure><h2 id="the-failure-inbox" tabindex="-1">The failure inbox <a class="header-anchor" href="#the-failure-inbox" aria-label="Permalink to &quot;The failure inbox&quot;">​</a></h2><p>The <strong>Failure inbox</strong> on Home lists up to 50 open clusters you can see, most recently seen first: <strong>headline</strong>, <strong>top clue</strong>, <strong>owner or assignee</strong>, <strong>affected tests</strong>, <strong>last seen</strong>, and exceptional <strong>badges</strong> (a regression on the default branch). A cluster seen only in local runs, in a project that runs in CI, stays out; <strong>Show them</strong> lists them.</p><h3 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h3><p>Each queue has a live count and is shareable as <code>?queue=</code>:</p><ul><li><strong>All open</strong>: every open cluster not snoozed.</li><li><strong>New</strong>: first seen, or seen again, since your previous browser session (kept per browser).</li><li><strong>Mine</strong>: <a href="#owners-and-assignees">yours</a>.</li><li><strong>Needs ticket</strong>: untracked default-branch clusters older than the binding&#39;s age (2 days by default; see <a href="./issue-tracking.html">issue tracking</a>).</li><li><strong>Regressions</strong>: regressed on the default branch, failing there still.</li><li><strong>Fix didn&#39;t hold</strong>: a fix landed, then regressed.</li><li><strong>Quarantine ready</strong>: <a href="./flaky-tests.html#quarantine-with-a-way-out">quarantined</a>, and the tests stopped failing.</li><li><strong>Merge suggestions</strong>: in a pending <a href="./ai-diagnosis.html#semantic-merging-optional">merge suggestion</a>.</li></ul><h3 id="triage-from-the-row-or-the-keyboard" tabindex="-1">Triage from the row or the keyboard <a class="header-anchor" href="#triage-from-the-row-or-the-keyboard" aria-label="Permalink to &quot;Triage from the row or the keyboard&quot;">​</a></h3><p>Open, resolve, ignore, quarantine, assign, snooze, link a known issue or create a tracker issue from the row, by mouse or <a href="/reference/keyboard-shortcuts.html#failure-inbox">key</a>; <code>x</code> selects rows for a <strong>bulk bar</strong>. Resolve, ignore, snooze and assign on one row can be undone for a few seconds. A known issue pins a URL; with an <a href="/operate/integrations.html">issue tracker</a> bound, Jira links unfurl and stay in sync (<a href="./issue-tracking.html">issue tracking</a>).</p><h2 id="owners-and-assignees" tabindex="-1">Owners and assignees <a class="header-anchor" href="#owners-and-assignees" aria-label="Permalink to &quot;Owners and assignees&quot;">​</a></h2><p>A cluster&#39;s <strong>owner</strong> is derived: the failing test&#39;s <code>piwi:owner</code> annotation, else, on the cluster and execution pages (not the inbox), the repository&#39;s <code>CODEOWNERS</code>. An <strong>assignee</strong> overrides it. <strong>Mine</strong> matches either against your name, username or email.</p><h2 id="the-cluster-page" tabindex="-1">The cluster page <a class="header-anchor" href="#the-cluster-page" aria-label="Permalink to &quot;The cluster page&quot;">​</a></h2><p>Top to bottom:</p><ol><li>The <a href="/guide/first-failure.html">situation block</a> across every test sharing the failure, headed by the latest failure&#39;s headline when it says more than the cluster&#39;s name. Its own lines: <ul><li><strong>the state line</strong>, right above <strong>Next</strong>;</li><li><strong>the occurrence sparkline</strong>: <em>N occurrences in M tests over D · last X ago</em>, naming a single test, <em>quarantined</em> if it is;</li><li><strong>What changed</strong>: commits and files since the last passing run (or your baseline), the diff, and with <a href="./server-coverage.html">coverage</a> the first <a href="/guide/concepts.html#suspect-lines">suspect line</a>. Missing setup shows what to set up (<a href="/guide/source-control.html#troubleshooting">troubleshooting</a>); <strong>Browse commits</strong> picks a baseline when none passed. One commit on both sides: the change is not in the code.</li></ul></li><li>The section <strong>Next</strong> points at (the AI diagnosis, the locator fix…) as its own card.</li><li><strong>Affected tests</strong>, picking whose evidence shows, then that evidence.</li><li><a href="./fix-plans.html#more-ways-to-fix"><strong>More ways to fix</strong></a>, then the <a href="#occurrences-over-time">occurrence chart</a> and the activity, folded.</li></ol><h3 id="the-state-line" tabindex="-1">The state line <a class="header-anchor" href="#the-state-line" aria-label="Permalink to &quot;The state line&quot;">​</a></h3><p><strong>One sentence with one verb</strong>, beside a colored dot: <em>still failing</em>, <em>not seen for N runs</em>, <em>fixed and verified, still open</em>, <em>fixed, but the diagnosed patch still applies at the fix&#39;s commit</em>, <em>stopped failing</em>, <em>regressed, the fix did not hold</em>, <em>resolved</em>, <em>ignored</em>, <em>snoozed</em> or <em>all tests quarantined</em>. It reconciles the triage status with the <a href="#did-the-fix-work">verdict</a>, offering <strong>the one action</strong> closing a gap unless <strong>Next</strong> does: <em>Mark resolved</em> (an open cluster stopped failing, or its ticket is Done and the failure stopped; a fix whose patch still applies keeps it in the <strong>Next</strong> menu), <em>Unsnooze</em>, or <em>Release</em> (all tests quarantined). <strong>Triage</strong> sets the status (open / resolved / ignored), note and assignee, and <a href="#snoozing">snoozes</a>; a status change keeps the note, a note edit the status.</p><h4 id="which-runs-count" tabindex="-1">Which runs count <a class="header-anchor" href="#which-runs-count" aria-label="Permalink to &quot;Which runs count&quot;">​</a></h4><p><em>Not seen for N runs</em> counts finished runs since the last failure, on its branch or the default branch, that ran the cluster&#39;s tests without that failure: never a Flake Lab run, bisect step, reproduction or <a href="./environment-incidents.html">environment incident</a>. A skipped, not-run or interrupted test was not run. A whole-suite run that reached its end counts even when a cluster test no longer exists; one stopped early (interrupted, cancelled, timed out, <code>maxFailures</code>) only if it ran the cluster&#39;s tests. A Done ticket&#39;s failure has stopped once such a run follows.</p><h3 id="occurrences-over-time" tabindex="-1">Occurrences over time <a class="header-anchor" href="#occurrences-over-time" aria-label="Permalink to &quot;Occurrences over time&quot;">​</a></h3><p>A chart of failures per day, week or month since first seen, marking the <strong>fix landed</strong>; the sparkline opens it.</p><h2 id="did-the-fix-work" tabindex="-1">Did the fix work? <a class="header-anchor" href="#did-the-fix-work" aria-label="Permalink to &quot;Did the fix work?&quot;">​</a></h2><p>When a run executes every test of a cluster and all pass, Piwi records the fix (run, commit, time open) and a verdict:</p><ul><li><strong>Stopped failing</strong>: the tests pass again, which a flaky test can do by accident.</li><li><strong>Diagnosis verified</strong>: the commits since the last failing run touched a file the <a href="./ai-diagnosis.html#validated-patches">suggested patch</a> named.</li><li><strong>Regressed</strong>: a fix was recorded, and the cluster fails again.</li></ul><p><strong>A fix needs every affected test to pass</strong> in the Playwright projects it last failed in that the run ran (a <code>--grep</code> over them is enough), in a run started after the last failing run, at another commit (a pass at the failing commit, such as a CI retry, is flake evidence the state line names), on the cluster&#39;s last failing branch or the default branch: a green pull-request branch leaves a cluster failing on <code>main</code> open. <strong>A regression needs a run started after the fix landed</strong>, failing on its branch or the default branch.</p><p><strong>Projects.</strong> A project the run left out but its config lists (another CI job runs it) says nothing; one the config no longer lists (removed, renamed) does not count, and a test that last failed only there is answered by a pass in any project. CI jobs loading different project lists (a config per job, a list from a variable) thus record a fix from any job where the tests pass: give them one list, and pick each job&#39;s projects with <code>--project</code>.</p><p>Only strong evidence moves the status. <em>Diagnosis verified</em> resolves an <strong>open</strong> cluster at once, so <em>fixed and verified, still open</em> reads only once something reopened it (a person, or a merge with a live cluster). <em>Regressed</em> reopens a <strong>resolved</strong> cluster, as does a new failure after a person resolved one with no fix on record; each adds a note line. <em>Stopped failing</em> changes nothing; an <em>ignored</em> cluster is never touched. The <code>cluster.fixed</code> and <code>cluster.regressed</code> <a href="./notifications.html">notifications</a> follow the verdict, and the <a href="./pr-feedback.html">pull-request</a> comment gains <strong>Fixed by this change</strong>, even with <em>only comment on failures</em>.</p><h2 id="snoozing" tabindex="-1">Snoozing <a class="header-anchor" href="#snoozing" aria-label="Permalink to &quot;Snoozing&quot;">​</a></h2><p><strong>Snoozing</strong> hides a cluster from every queue, status untouched. <strong>1 day</strong> and <strong>1 week</strong> return it then; <strong>Until it recurs</strong> returns it to <strong>New</strong> when a run fails it, badged <strong>snoozed, back</strong> until your next visit.</p><h2 id="from-an-ai-agent" tabindex="-1">From an AI agent <a class="header-anchor" href="#from-an-ai-agent" aria-label="Permalink to &quot;From an AI agent&quot;">​</a></h2><p>Over the <a href="/features/mcp.html">MCP server</a>, <code>list_open_clusters</code> takes the same <code>queue</code>, and each action above has a <a href="/reference/mcp-tools.html">tool</a>: <code>triage_cluster</code>, <code>decide_merge_suggestion</code>, <code>move_tests_to_new_cluster</code>, <code>rerun_cluster_in_ci</code>, <code>link_issue</code> and <code>unlink_issue</code>.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',39)),s(o),e[2]||(e[2]=a('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/mass-failure.html">Triage a run gone red</a>: a red run collapsed into causes</li><li><a href="./ai-diagnosis.html">AI diagnosis</a>: a cluster explained against your diff</li><li><a href="./evidence.html">Failure evidence</a>: one execution&#39;s evidence</li><li><a href="/guide/concepts.html#error-fingerprint-failure-cluster">Core concepts</a>: the terms</li></ul>',2))])}const q=h(g,[["render",f]]);export{_ as __pageData,q as default};
